import { Component, inject } from '@angular/core';
import { FormBuilder, ReactiveFormsModule, Validators } from '@angular/forms';

@Component({
  selector: 'app-root',
  standalone: true,
  imports: [ReactiveFormsModule],
  templateUrl: './app.component.html',
  styleUrls: ['./app.component.css']
})
export default class AppComponent {
  private fb = inject(FormBuilder);

  // Index of the current step (0, 1, 2)
  currentStep = 0;

  // Provide a concrete FormGroup instance so [formGroup] always receives something
  // Validators are kept minimal; candidate will adjust validation & navigation logic.
  form: any = this.fb.group({
    basic: this.fb.group({
      name: [''],
      email: ['']
    }),
    address: this.fb.group({
      street: [''],
      city: [''],
      country: [''],
      postalCode: ['']
    })
  });

  // Convenience getters for nested groups (used in the template)
  get basicGroup(): any {
    return this.form.get('basic') as any;
  }

  get addressGroup(): any {
    return this.form.get('address') as any;
  }

  get isFirstStep(): boolean {
    return this.currentStep === 0;
  }

  get isLastStep(): boolean {
    return this.currentStep === 2;
  }

  // Only allow going to the next step when the current group's controls are valid
  // (candidate will implement real logic here)
  get canGoNext(): boolean {
    return false;
  }

  // TODO: move to the next step (mark the current group as touched and check validity)
  next(): void {}

  // TODO: move to the previous step if not on the first step
  prev(): void {}

  // TODO: mark the whole form as touched and submit the data if valid
  submit(): void {}
}

export { AppComponent };

